const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cairo = ee.Geometry.Point([31.2357, 30.0444]); // Cairo coordinates
  const roi = cairo.buffer(20000); // 20km buffer around Cairo, focusing east of Nile

  // Time periods
  const period1 = ['1984-07-01', '1984-07-31'];
  const period2 = ['2019-09-01', '2019-09-30'];

  // 2. Data Acquisition - Landsat 5 for 1984, Landsat 8 for 2019
  let col1 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(roi)
    .filterDate(period1[0], period1[1])
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(roi)
    .filterDate(period2[0], period2[1])
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  // Check collection sizes
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`1984 Images: ${size1}, 2019 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get median composites
  const img1 = col1.median();
  const img2 = col2.median();

  // 3. Built-up area detection using NDBI
  // NDBI = (SWIR - NIR) / (SWIR + NIR)
  const addNDBI = function(image) {
    // Landsat 5: B5=SWIR, B4=NIR
    // Landsat 8: B6=SWIR, B5=NIR
    const swir = image.select('SR_B6'); // SWIR band
    const nir = image.select('SR_B5');  // NIR band
    const ndbi = swir.subtract(nir).divide(swir.add(nir)).rename('NDBI');
    return image.addBands(ndbi);
  };

  const img1_ndbi = addNDBI(img1);
  const img2_ndbi = addNDBI(img2);

  // 4. Calculate mean NDBI values
  const reducer = ee.Reducer.mean();

  const stats1 = img1_ndbi.select('NDBI').reduceRegion({
    reducer: reducer,
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = img2_ndbi.select('NDBI').reduceRegion({
    reducer: reducer,
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('NDBI').getInfo();
  const mean2 = stats2.get('NDBI').getInfo();

  // Check for valid results
  if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`1984 Mean NDBI: ${mean1.toFixed(4)}`);
  console.log(`2019 Mean NDBI: ${mean2.toFixed(4)}`);
  console.log(`Change: ${(mean2 - mean1).toFixed(4)}`);

  // 5. Final decision
  if (mean2 > mean1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
